// Per-agency IG service / agency fees, keyed by campaign id.
// Sourced from each campaign sheet's IG section (agency fee rows).
// These are agency fees on top of creator spend — surfaced in CampaignIGDetail.
export const IG_SERVICE_FEES = {
  director: { Rakugo: 116484 },
  vfx:      { Rakugo: 48585, Aevy: 8475 },
  ss:       { Rakugo: 8620, Aevy: 18862.5, Heek: 10650 },
  sd2:      { Rakugo: 74274, Aevy: 14602, Heek: 8068 },
  oaw:      { Rakugo: 56860 },
  cb:       { Heek: 4011 },
};

export function igServiceFees(campaignId) {
  return IG_SERVICE_FEES[campaignId] || {};
}
export function igServiceFeeTotal(campaignId) {
  return Object.values(igServiceFees(campaignId)).reduce((a, b) => a + b, 0);
}

export const IG_CAMPAIGNS = {
  sd2: { label: "Seedance 2.0", data: SD2_IG },
  oaw: { label: "OpenArt Worlds", data: OAW_IG },
  cb: { label: "Character Builder", data: CB_IG },
  vfx: { label: "VFX", data: VFX_IG },
  director: { label: "Director", data: DIRECTOR_IG },
  ss: { label: "SmartShot", data: SS_IG },
};

// Helpers for the new + legacy schemas. Use these everywhere instead of
// reading raw fields, so a creator with one IG post or many cross-posts
// renders identically and `carousel: true` items can be excluded from CPM.
export function igItemViews(item) {
  return item.totalViews ?? item.views ?? 0;
}
export function igItemPosts(item) {
  if (item.posts) return item.posts;
  if (item.link) return [{ platform: "ig", views: item.views ?? 0, link: item.link }];
  return [];
}
